const lockChain = `-- name: LockChain :one
SELECT id
FROM escalation_chains
WHERE org_id = $1 AND public_id = $2
FOR NO KEY UPDATE
`

type LockChainParams struct {
	OrgID    int64
	PublicID string
}

// LockChain locks a chain for a change, FOR NO KEY UPDATE: the saves of Routes and Teams that name it take it FOR KEY
// SHARE and do not wait for a change of it.
func (q *Queries) LockChain(ctx context.Context, arg LockChainParams) (int64, error) {
	row := q.db.QueryRow(ctx, lockChain, arg.OrgID, arg.PublicID)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const lockChainForDeletion = `-- name: LockChainForDeletion :one
SELECT id
FROM escalation_chains
WHERE org_id = $1 AND public_id = $2
FOR UPDATE
`

type LockChainForDeletionParams struct {
	OrgID    int64
	PublicID string
}

// LockChainForDeletion locks a chain FOR UPDATE before its deletion, which conflicts with the FOR KEY SHARE of a save
// of a Route or a Team that names it: either that save committed and its entry refuses the deletion, or it waits and
// then finds the chain gone.
func (q *Queries) LockChainForDeletion(ctx context.Context, arg LockChainForDeletionParams) (int64, error) {
	row := q.db.QueryRow(ctx, lockChainForDeletion, arg.OrgID, arg.PublicID)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const lockOwningTeam = `-- name: LockOwningTeam :one
SELECT id, public_id, name, slug
FROM teams
WHERE org_id = $1 AND public_id = $2 AND deleted_at IS NULL
FOR SHARE
`

type LockOwningTeamParams struct {
	OrgID    int64
	PublicID string
}

type LockOwningTeamRow struct {
	ID       int64
	PublicID string
	Name     string
	Slug     string
}

// LockOwningTeam reads a Team that is not deleted as the owner of a chain FOR SHARE, before the chain's row: the
// deletion of the Team, which locks it first FOR NO KEY UPDATE and then reads the chains it owns, either sees the chain
// or makes this save wait and then find the Team deleted.
func (q *Queries) LockOwningTeam(ctx context.Context, arg LockOwningTeamParams) (LockOwningTeamRow, error) {
	row := q.db.QueryRow(ctx, lockOwningTeam, arg.OrgID, arg.PublicID)
	var i LockOwningTeamRow
	err := row.Scan(
		&i.ID,
		&i.PublicID,
		&i.Name,
		&i.Slug,
	)
	return i, err
}

