const resolveSchedules = `-- name: ResolveSchedules :many
SELECT sc.id, sc.public_id, sc.name, t.public_id AS team_public_id, t.name AS team_name, t.slug AS team_slug,
       (t.deleted_at IS NOT NULL)::boolean AS team_deleted
FROM schedules sc
JOIN teams t ON t.org_id = sc.org_id AND t.id = sc.team_id
WHERE sc.org_id = $1 AND sc.public_id = ANY($2::text[])
ORDER BY sc.id
FOR KEY SHARE OF sc
`

type ResolveSchedulesParams struct {
	OrgID     int64
	PublicIds []string
}

type ResolveSchedulesRow struct {
	ID           int64
	PublicID     string
	Name         string
	TeamPublicID string
	TeamName     string
	TeamSlug     string
	TeamDeleted  bool
}

// ResolveSchedules reads the Schedules among the public_ids with their Teams, FOR KEY SHARE in id order: the deletion
// of a Schedule locks it FOR UPDATE and then reads the steps that name it, so either it sees this save's step or this
// save waits and then finds the Schedule gone. KEY SHARE, unlike SHARE, does not conflict with the NO KEY UPDATE of a
// change of a Schedule, so a save naming two Schedules never deadlocks with making one of them main.
func (q *Queries) ResolveSchedules(ctx context.Context, arg ResolveSchedulesParams) ([]ResolveSchedulesRow, error) {
	rows, err := q.db.Query(ctx, resolveSchedules, arg.OrgID, arg.PublicIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ResolveSchedulesRow{}
	for rows.Next() {
		var i ResolveSchedulesRow
		if err := rows.Scan(
			&i.ID,
			&i.PublicID,
			&i.Name,
			&i.TeamPublicID,
			&i.TeamName,
			&i.TeamSlug,
			&i.TeamDeleted,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

