const updateChain = `-- name: UpdateChain :exec
UPDATE escalation_chains
SET name = $1, description = $2, owning_team_id = $3::bigint,
    updated_at = $4, version = version + 1
WHERE org_id = $5 AND id = $6
`

type UpdateChainParams struct {
	Name         string
	Description  string
	OwningTeamID pgtype.Int8
	Now          time.Time
	OrgID        int64
	ID           int64
}

// UpdateChain replaces the fields of a chain and bumps its version.
func (q *Queries) UpdateChain(ctx context.Context, arg UpdateChainParams) error {
	_, err := q.db.Exec(ctx, updateChain,
		arg.Name,
		arg.Description,
		arg.OwningTeamID,
		arg.Now,
		arg.OrgID,
		arg.ID,
	)
	return err
}
